 // ─── LIVE ODDS STATE ─────────────────────────────────────────────
 const [liveOdds, setLiveOdds] = useState({});
 const [homeTab, setHomeTab] = useState('home');
  // Live scores (Phase 2/3): poll the normalized feed for today+yesterday; matches picks by team name.
  const [liveGames, setLiveGames] = useState([]);
  const [gamecastSel, setGamecastSel] = useState(null);
  const [histOpenWeeks,setHistOpenWeeks]=useState({});
  const [histOpenDays,setHistOpenDays]=useState({});
  const _liveTimer = useRef(null);
  const _etDate = (d) => { try { const pp = new Intl.DateTimeFormat("en-CA",{timeZone:"America/New_York",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(d); const gg=(t)=>pp.find(x=>x.type===t).value; return gg("year")+"-"+gg("month")+"-"+gg("day"); } catch(e){ return new Date(d).toISOString().slice(0,10); } };
  useEffect(() => {
    let alive = true;
    const pull = async () => {
      try {
        const today=_etDate(new Date()), yest=_etDate(new Date(Date.now()-86400000));
        const r = await fetch(API_BASE+`/api/livescores?dates=${today},${yest}`);
        const j = await r.json();
        if (alive && j && Array.isArray(j.games)) setLiveGames(j.games);
      } catch(e){}
    };
    pull();
    _liveTimer.current = setInterval(pull, 30000);
    return () => { alive=false; if(_liveTimer.current) clearInterval(_liveTimer.current); };
  }, []);
  const openGamecast = async (pick) => {
    let g = liveMatch(pick, liveGames);
    if (!g && pick && pick.game_date) {
      try {
        const d = new Date(pick.game_date);
        const ds=_etDate(d), dp=_etDate(new Date(d.getTime()-86400000)), dn=_etDate(new Date(d.getTime()+86400000));
        const r = await fetch(API_BASE+`/api/livescores?dates=${ds},${dp},${dn}`);
        const j = await r.json();
        if (j && Array.isArray(j.games)) g = liveMatch(pick, j.games);
      } catch(e){}
    }
    if (g) setGamecastSel({ game:g, pick });
  };
 const [homeMode, setHomeMode] = useState('leagues');
 // No leagues yet -> route into the Solo lobby (never the phantom NFL league).
 useEffect(()=>{ if(!leaguesLoading && realLeagues.length===0 && !isSoloModeRef.current){ setHomeMode('solo'); setSoloModeWithRef(true); } }, [leaguesLoading, realLeagues.length]);
 const [leagueSubTab, setLeagueSubTab] = useState("overview");
 const [tickerGames, setTickerGames] = useState([]); // raw games for the ticker
 const [espnGames, setEspnGames] = useState([]); // ESPN scoreboard with IDs
 const [weekResult, setWeekResult] = useState(null);
 const [recapPicks, setRecapPicks] = useState([]); // {won, myPts, oppPts, oppName, week}
 const [leagueRecap, setLeagueRecap] = useState(null);
 const [strayPicks, setStrayPicks] = useState([]);
 const [leagueRecapLoading, setLeagueRecapLoading] = useState(false);
 const [gameSheet, setGameSheet] = useState(null); // { tickerGame, espnGame, detail }
 const [gameTeamTab, setGameTeamTab] = useState('matchup'); // 'matchup' | 'away' | 'home' 
 const [gameLoading, setGameLoading] = useState(false);
 const [gameRead, setGameRead] = useState({});
 const [oddsLoading, setOddsLoading] = useState(false);
 const [soloGamesAll, setSoloGamesAll] = useState(false);
 const [oddsError, setOddsError] = useState(false);
 // oddsLastFetched persisted in localStorage so cache survives page refreshes

 const SPORT_KEYS = { nfl:"americanfootball_nfl", nba:"basketball_nba", mlb:"baseball_mlb", ncaaf:"americanfootball_ncaaf" };

 const _oddsInFlight = useRef({});
 // In-flight guard. Three separate effects can ask for the same sport within a few
 // frames of each other; without this the second one bills a second call before the
 // first has returned. Keyed off a ref so it survives re-renders.
 const fetchLiveOdds = async (sportId) => {
   if(!sportId) return;
   if(_oddsInFlight.current[sportId]) return;
   _oddsInFlight.current[sportId] = true;
   try{ return await _fetchLiveOddsInner(sportId); }
   finally{ _oddsInFlight.current[sportId] = false; }
 };
 const _fetchLiveOddsInner = async (sportId) => {
 // Cache for 10 minutes


 setOddsLoading(true);
 setOddsError(false);
 try {
 const sportKey = SPORT_KEYS[sportId];
 if(!sportKey) { setOddsLoading(false); return; }

 // Fetch h2h + spreads + totals in one call
 const res = await fetch(API_BASE+`/api/odds?sport=${sportKey}`, { headers: await authHeaders() });
 if(!res.ok) throw new Error(`API error ${res.status}`);
 const payload = await res.json();
 console.log(`[odds] ${sportId} games:`, (payload.games||payload)?.length, "| quota used:", payload.used, "remaining:", payload.remaining);
 const games = payload.games || payload; // handle both formats

 const ml = [], spread = [], ou = [], longshot = [];

 games.forEach((game, gi) => {
 const home = game.home_team;
 const away = game.away_team;
 const gameLabel = `${away} @ ${home}`;
 const dk = game.bookmakers?.[0];
 if(!dk) return;

 const h2h = dk.markets?.find(m=>m.key==="h2h");
 const spreads = dk.markets?.find(m=>m.key==="spreads");
 const totals = dk.markets?.find(m=>m.key==="totals");

 // Moneyline — both sides
 h2h?.outcomes?.forEach((o, oi) => {
 const american = o.price >= 0 ? `+${o.price}` : `${o.price}`;
 ml.push({
 id: `live_ml_${gi}_${oi}`,
 game: gameLabel,
 pick: o.name,
 odds: american,
 impliedOdds: o.price,
 edge: (o.edge!=null?o.edge:null),
 gameTime: game.commence_time, awayPitcher: game.away_pitcher||null, homePitcher: game.home_pitcher||null,
 eventId: game.id, marketKey: "h2h", outcome: o.name, point: null,
 selKey: `${game.id}|h2h|${o.name}|`,
 });
 });

 // Spreads — both sides
 spreads?.outcomes?.forEach((o, oi) => {
 const american = o.price >= 0 ? `+${o.price}` : `${o.price}`;
 const sign = o.point >= 0 ? `+${o.point}` : `${o.point}`;
 spread.push({
 id: `live_sp_${gi}_${oi}`,
 game: gameLabel,
 pick: `${o.name} ${sign}`,
 odds: american,
 impliedOdds: o.price,
 edge: (o.edge!=null?o.edge:null),
 gameTime: game.commence_time, awayPitcher: game.away_pitcher||null, homePitcher: game.home_pitcher||null,
 eventId: game.id, marketKey: "spreads", outcome: o.name, point: o.point,
 selKey: `${game.id}|spreads|${o.name}|${o.point}`,
 });
 });

 // Totals — over/under
 totals?.outcomes?.forEach((o, oi) => {
 const american = o.price >= 0 ? `+${o.price}` : `${o.price}`;
 ou.push({
 id: `live_ou_${gi}_${oi}`,
 game: gameLabel,
 pick: `${o.name} ${o.point}`,
 odds: american,
 impliedOdds: o.price,
 edge: (o.edge!=null?o.edge:null),
 gameTime: game.commence_time, awayPitcher: game.away_pitcher||null, homePitcher: game.home_pitcher||null,
 eventId: game.id, marketKey: "totals", outcome: o.name, point: o.point,
 selKey: `${game.id}|totals|${o.name}|${o.point}`,
 });
 });
 });

 // Fetch live player props from separate endpoint
 let prop = []; // live props only — blank if the feed has none for this sport
 try {
 const propsRes = await fetch(API_BASE+`/api/props?sport=${sportKey}`, { headers: await authHeaders() });
 if(propsRes.ok) {
 const propsPayload = await propsRes.json();
 if(propsPayload.props && propsPayload.props.length > 0) {
 prop = propsPayload.props;
 }
 }
 } catch(e) {
 console.warn("Props fetch failed — leaving props empty:", e);
 }

 // Fetch ESPN scoreboard to get event IDs for game detail sheet
 try {
 const espnRes = await fetch(API_BASE+`/api/espn?sport=${sportKey}`);
 if(espnRes.ok) {
 const espnPayload = await espnRes.json();
 if(espnPayload.games) setEspnGames(prev => [...(prev||[]).filter(x => x._sport !== sportId), ...espnPayload.games.map(x => ({...x, _sport: sportId}))]);
 }
 } catch(e) { console.warn("ESPN scoreboard fetch failed:", e); }

 // Store raw games for the ticker — merge by sport so one sport's fetch doesn't wipe another's
 setTickerGames(prev => { const _fresh = games.map(g => ({ away: g.away_team, home: g.home_team, time: g.commence_time, sport: sportId })); return [...(prev||[]).filter(x => x.sport !== sportId), ..._fresh]; });

 // A longshot is ANY bet priced +400 or longer — NOT just a moneyline. This was
 // collected inside the h2h loop only, so a +650 spread, a +900 total or a +1100 prop
 // was invisible to every longshot slot. On a near-even one-game slate (Mets +112 /
 // Phillies -124) that meant the 7x longshot could never fill from anything.
 const LS_MIN = 400;
 const _amt = (b) => (b && b.impliedOdds != null) ? b.impliedOdds
  : parseInt(String((b && b.odds) || "").replace(/\u2212/g, "-").replace(/[^-+0-9]/g, ""), 10);
 const _lsSeen = new Set();
 [...ml, ...spread, ...ou, ...prop].forEach(b => {
  const a = _amt(b);
  if (!(a >= LS_MIN)) return;
  const k = b.selKey || b.id;
  if (_lsSeen.has(k)) return;
  _lsSeen.add(k);
  longshot.push({ ...b, id: `live_ls_${b.id}` });
 });

 setLiveOdds(prev => ({
 ...prev,
 [sportId]: { ml, spread, ou, longshot, prop }
 }));

 } catch(e) {
 console.error("Odds API error [" + sportId + "]:", errText(e));
 setOddsError(true);
 } finally {
 setOddsLoading(false);
 }
 };

 // Lazy per-event period-odds fetch (1st half / first-5 / YRFI-NRFI). Only called for
 // games in a custom league that actually has a period slot. Cached: cats default to []
 // so a sport isn't re-fetched once attempted.
 const fetchPeriodOdds = async (sportId, eventIds, periodTypes) => {
 if(!eventIds.length || !periodTypes.length) return;
 const sportKey = SPORT_KEYS[sportId]; if(!sportKey) return;
 const marketKeys = [...new Set(periodTypes.map(t=>PERIOD_MARKETS[t]).filter(Boolean))];
 if(!marketKeys.length) return;
 try {
 const res = await fetch(API_BASE+`/api/eventodds?sport=${sportKey}&events=${eventIds.join(",")}&markets=${marketKeys.join(",")}`, { headers: await authHeaders() });
 if(!res.ok) return;
 const data = await res.json();
 const grouped = {}; periodTypes.forEach(t=>{ grouped[t]=[]; });
 (data.bets||[]).forEach(b=>{ if(grouped[b.category]) grouped[b.category].push(b); });
 setLiveOdds(prev=>({ ...prev, [sportId]: { ...(prev[sportId]||{}), ...grouped } }));
 } catch(e) { console.warn("period odds fetch failed", e); }
 };

 // Use live odds if available, else fall back to hardcoded
 // Multi-sport: merge bets from all sports in the league
 const leagueSports = (activeLeague.sports && activeLeague.sports.length > 0)
   ? activeLeague.sports
   : [activeLeague.sport || "nfl"];
 const BETS = (() => {
   const merged = {ml:[],spread:[],ou:[],prop:[],longshot:[],ml_h1:[],spread_h1:[],ou_h1:[],ml_f5:[],spread_f5:[],ou_f5:[],yrfi:[],nrfi:[]};
   const tag = (arr, sp) => (arr||[]).map(b=>({...b, _sport:sp}));
   leagueSports.forEach(sp => {
     const odds = liveOdds[sp];
     if(!odds) return; // not loaded yet for this sport
     merged.ml.push(...tag(odds.ml||[], sp));
     merged.spread.push(...tag(odds.spread||[], sp));
     merged.ou.push(...tag(odds.ou||[], sp));
     merged.prop.push(...tag(odds.prop||[], sp));
     merged.longshot.push(...tag(odds.longshot||[], sp));
     PERIOD_CATS.forEach(c=>{ merged[c].push(...tag(odds[c]||[], sp)); });
   });
   return merged;
 })();
 const isLiveOdds = leagueSports.some(sp => !!liveOdds[sp]);

