 const fetchLeagueTrophies = async (leagueId) => {
 const {data:picks} = await supabase
 .from("picks")
 .select("*")
 .eq("league_id", leagueId)
 .neq("result", "pending");
 if(!picks||!picks.length) { setLeagueTrophies([]); return; }

 const {data:members} = await supabase.from("league_members").select("user_id").eq("league_id", leagueId);
 if(!members||!members.length) { setLeagueTrophies([]); return; }
 const userIds = members.map(m=>m.user_id);
 const {data:users} = await supabase.from("public_profiles").select("id,username").in("id",userIds);

 const getName = (uid) => {
 const u = users?.find(x=>x.id===uid);
 return u?.username || "Unknown";
 };
 const isMe = (uid) => uid === user?.id;

 // Stats per user
 const stats = {};
 // Chronological, not database order. Supabase returns rows however it likes, so
 // walking them unsorted built streaks out of a shuffled deck. game_date is when
 // the result actually landed; created_at only says when the pick was entered.
 const _when=(x)=>new Date(x.game_date||x.created_at||0).getTime()||0;
 [...picks].sort((a,b)=>_when(a)-_when(b)).forEach(p=>{
 if(!stats[p.user_id]) stats[p.user_id]={wins:0,losses:0,points:0,longshotPts:0,streak:0,maxStreak:0};
 const s = stats[p.user_id];
 if(p.result==="W") {
 s.wins++;
 s.points += parseFloat(p.points_earned||0);
 if(p.slot==="longshot"||p.slot?.startsWith("longshot_")) s.longshotPts += parseFloat(p.points_earned||0);
 s.streak++;                                  /* run of consecutive WINS only */
 s.maxStreak = Math.max(s.maxStreak, s.streak);
 } else {
 s.losses++;
 s.streak = 0;
 }
 });

 const uids = Object.keys(stats);
 if(!uids.length) { setLeagueTrophies([]); return; }

 const byPoints = [...uids].sort((a,b)=>stats[b].points-stats[a].points);
 const RATE_FLOOR = 10;   /* graded picks needed before a win rate is rankable */
 const graded = (u)=>stats[u].wins+stats[u].losses;
 const rateEligible = uids.filter(u=>graded(u)>=RATE_FLOOR);
 const byWinRate = [...rateEligible].sort((a,b)=>{
 const ra = stats[a].wins/(graded(a)||1);
 const rb = stats[b].wins/(graded(b)||1);
 return (rb-ra) || (graded(b)-graded(a));   /* ties go to the bigger sample */
 });
 const byStreak = [...uids].sort((a,b)=>stats[b].maxStreak-stats[a].maxStreak);
 const byLongshot = [...uids].sort((a,b)=>stats[b].longshotPts-stats[a].longshotPts);

 // Carry the LEADER's value and YOURS. Previously a trophy only knew who held it, so
 // the tab was six facts about other people with nothing to compare against.
 // unit drives formatting: pts | pct | int.
 const winRate = (uid) => { const st = stats[uid]; if(!st) return 0; const n = st.wins + st.losses; return n ? st.wins/n : 0; };
 const mkT = (id, name, desc, color, order, val, unit, pending) => {
  const leadUid = order[0];
  const mine = (user && user.id && stats[user.id]) ? (val(user.id) || 0) : 0;
  // No eligible holder yet: show the trophy unclaimed rather than crowning a
  // one-pick player. lead 0 makes every gap bar read as wide open.
  if(!leadUid) return { id, name, desc, color, holder:pending||"Unclaimed", isYou:false, lead:0, mine, unit };
  return { id, name, desc, color, holder:getName(leadUid), isYou:isMe(leadUid), lead:val(leadUid)||0, mine, unit };
 };
 const trophies = [
  mkT("whale","The Whale","Most total points",IOS.green,byPoints,(u)=>stats[u]?stats[u].points:0,"pts"),
  mkT("sharp","Sharpshooter","Highest win rate (10+ picks)",IOS.yellow,byWinRate,winRate,"pct","Needs 10 picks"),
  mkT("hot","Hot Hand","Longest win streak",IOS.orange,byStreak,(u)=>stats[u]?stats[u].maxStreak:0,"int"),   /* maxStreak here is win-only, see loop above */
  mkT("longshot","Longshot King","Most points from longshots",IOS.pink,byLongshot,(u)=>stats[u]?stats[u].longshotPts:0,"pts"),
 ];
 setLeagueTrophies(trophies);
 };

 useEffect(()=>{
   const code=userProfile&&userProfile.referral_code; if(!code){ setRefStats({signups:0,paying:0,people:[]}); return; }
   let cancelled=false;
   (async()=>{ try{ const {data}=await supabase.from("public_profiles").select("id,username,is_pro").eq("referred_by",code); if(cancelled) return; const rows=data||[];
     const people=rows.map(r=>({id:r.id, name:r.username||"New player", pro:r.is_pro===true}))
       .sort((a,b)=>(b.pro?1:0)-(a.pro?1:0)||String(a.name).localeCompare(String(b.name)));
     setRefStats({signups:rows.length, paying:rows.filter(r=>r.is_pro===true).length, people}); }catch(e){} })();
   return ()=>{cancelled=true;};
 }, [userProfile&&userProfile.referral_code]);
 const fetchLeaderboard = async (tf) => {
   if(lbCache[tf]) return lbCache[tf];
   setLbLoading(true);
   try{ const {data,error}=await supabase.rpc("global_leaderboard",{tf}); if(!error){ const rows=data||[]; setLbCache(prev=>({...prev,[tf]:rows})); setLbLoading(false); return rows; } }catch(e){}
   setLbLoading(false); return [];
 };
 useEffect(()=>{ if(user) fetchLeaderboard("all"); }, [user]);

 // ── Player profile sheet: who we're looking at + their RPC payload. The ref
 // guards against a slow fetch for player A landing after the user tapped B
 // (same stale-closure class of bug as the fetchMyPicks boot flash).
 const [profileView, setProfileView] = useState(null);
 const [profileData, setProfileData] = useState(null);
 const [profileLoading, setProfileLoading] = useState(false);
 const profileReqRef = useRef(null);
 // Data export. The file is built server-side so it is complete regardless of
 // what RLS lets the browser read. Delivery differs by platform: a WKWebView
 // ignores <a download>, so on device we hand off to the share sheet instead.
 const downloadMyData = async () => {
   if(expBusy) return;
   setExpBusy(true); setExpMsg("");
   try{
     const {data:sess}=await supabase.auth.getSession();
     const tok=sess&&sess.session&&sess.session.access_token;
     const r=await fetch(API_BASE+"/api/export-data",{method:"POST",
       headers:{"Content-Type":"application/json","Authorization":"Bearer "+tok},
       body:JSON.stringify({format:"html"})});
     if(!r.ok){ let m="Could not build your export."; try{ const j=await r.json(); if(j.error) m=j.error; }catch(e){}
       setExpBusy(false); setExpMsg(m); return; }
     const text=await r.text();
     const name="picklock-data-"+new Date().toISOString().slice(0,10)+".html";
     let handled=false;
     if(IS_NATIVE && navigator.share){
       try{
         const file=new File([text],name,{type:"text/html"});
         if(navigator.canShare && navigator.canShare({files:[file]})){ await navigator.share({files:[file],title:name}); handled=true; }
         else { await navigator.share({title:name,text}); handled=true; }
       }catch(e){ if(e && e.name==="AbortError"){ setExpBusy(false); setExpMsg(""); return; } }
     }
     if(!handled){
       const url=URL.createObjectURL(new Blob([text],{type:"text/html"}));
       const a=document.createElement("a"); a.href=url; a.download=name;
       document.body.appendChild(a); a.click(); a.remove();
       setTimeout(()=>{ try{ URL.revokeObjectURL(url); }catch(e){} },1000);
     }
     setExpBusy(false); setExpMsg("Saved "+name);
   }catch(e){ setExpBusy(false); setExpMsg("Could not reach the server. Try again."); }
 };

 // Opening a game sheet is identical from either board; GameCard calls this.
 const openGameSheet = async ({ g, away, home, espn, isLive, gameTime, odds }) => {
   setGameSheet({ tickerGame:{...g, away, home, isLive, timeStr:gameTime}, espnGame:espn, detail:null, odds });
   setGameTeamTab("matchup");
   if(espn?.id){
     setGameLoading(true);
     try{
       const _sk = SPORT_KEYS[(g && g.sport) || activeLeague?.sport];
       const r = await fetch(API_BASE+`/api/espn?sport=${_sk}&gameId=${espn.id}`);
       if(r.ok){ const d = await r.json(); setGameSheet(prev=>({...prev, detail:d})); }
     }catch(e){}
     finally{ setGameLoading(false); }
   }
 };

 // Roll a finished season into the archive and start the next one. The RPC does
 // the work in one transaction: snapshot, copy, verify, then clear. It refuses
 // unless the caller is the commissioner and a champion has been crowned.
 useEffect(()=>{ try{ document.documentElement.classList.toggle("pk-fullscreen", !!showNewLeague); }catch(e){} }, [showNewLeague]);
 const [rollBusy, setRollBusy] = useState(false);
 // League history is served whole by one definer RPC, so there is nothing to
 // stitch client-side and no way for a non-member to read another league.
 const [leagueHistory, setLeagueHistory] = useState(null);
 const [historyFor, setHistoryFor] = useState(null);
 const historyReqRef = useRef(null);
 const openLeagueHistory = async () => {
   if(!activeLeague || !activeLeague.id) return;
   const lid = activeLeague.id;
   historyReqRef.current = lid;
   setScreen("leaguehistory");
   if(historyFor === lid) return;                 // already loaded for this league
   try{
     const { data } = await supabase.rpc("get_league_history", { target_league: lid });
     if(historyReqRef.current !== lid) return;    // switched away mid-fetch
     setLeagueHistory(data || null); setHistoryFor(lid);
   }catch(e){}
 };
 const rollSeason = async () => {
   if(rollBusy || !activeLeague || !activeLeague.id) return;
   const _next = Number(activeLeague.season_number||1) + 1;
   if(!window.confirm("Start Season "+_next+"?\n\nThis season's standings, champion and trophies are kept permanently. Everyone starts 0-0.")) return;
   setRollBusy(true);
   try{
     const { data, error } = await supabase.rpc("roll_league_season", { target_league: activeLeague.id, new_name: null });
     if(error || !data || data.ok !== true){
       setRollBusy(false);
       alert((data && data.error) || errText(error) || "Could not start the new season.");
       return;
     }
     haptic("success");
     // Everything league-scoped is now stale by definition.
     setBracketMatchups([]); setBracketFor(null);
     setAllMatchups([]); setMatchupsFor(null);
     setRealStandings([]); setStandingsFor(null);
     setWeekPicks([]); setSavedPicks(null); setLeagueTrophies([]);
     await fetchLeagues(user.id);
     setRollBusy(false); setLeagueTab("standings");
     alert("Season "+_next+" is live. Season "+data.archived_season+" is saved in league history.");
   }catch(e){ setRollBusy(false); alert("Could not reach the server. Please try again."); }
 };

 const openUserProfile = async (userId, seed) => {
   if(!userId) return;
   const id = String(userId);
   profileReqRef.current = id;
   setProfileView({ userId:id, seed:seed||null });
   setProfileData(null); setProfileLoading(true);
   if(!lbCache["all"]) fetchLeaderboard("all");   // rank chip needs the board
   try{
     const { data, error } = await supabase.rpc("get_public_profile", { target: userId });
     if(profileReqRef.current!==id) return;         // user already tapped someone else
     if(!error && data && data.profile){ setProfileData(data); }
   }catch(e){}
   if(profileReqRef.current===id) setProfileLoading(false);
 };
 const fetchUserProfile = async (uid) => {
 const {data} = await supabase.from("users").select("id,username,email,is_pro,push_enabled,notif_results,notif_grades,notif_reminder,notif_league,notif_plok,referral_code,referred_by,birth_date,is_founder,founder_number").eq("id",uid).maybeSingle();
 if(data) {
 setUserProfile(data);
 // DB is source of truth for pro status
 const proVal = data.is_pro === true;
 setIsPro(proVal);
 try{ posthog.identify(data.id, { username: data.username||null, is_pro: data.is_pro===true }); }catch(e){}
 try { localStorage.setItem("picklock_is_pro", proVal ? "true" : "false"); } catch(e) {}
 if(!data.username) {
 const createdAt = data.created_at ? new Date(data.created_at).getTime() : 0;
 const ageSeconds = (Date.now() - createdAt) / 1000;
 if(ageSeconds > 30) setShowUsernamePrompt(true);
 }
 } else {
 // No public.users row yet (common with email confirmation on: the signup-time insert
 // ran before the user was authenticated). Create it now that we're logged in.
 try {
 const {data:_au}=await supabase.auth.getUser();
 const _meta=(_au&&_au.user&&_au.user.user_metadata)||{};
 const _myRef=Math.random().toString(36).substring(2,8).toUpperCase();
 const _row={ id:uid, email:(_au&&_au.user&&_au.user.email)||null, referral_code:_myRef };
 if(_meta.username) _row.username=_meta.username;
 if(_meta.referred_by) _row.referred_by=_meta.referred_by;
 const {data:_created}=await supabase.from("users").upsert(_row,{onConflict:"id"}).select("id,username,email,is_pro,push_enabled,notif_results,notif_grades,notif_reminder,notif_league,notif_plok,referral_code,referred_by,birth_date,is_founder,founder_number").maybeSingle();
 if(_created){ setUserProfile(_created); setIsPro(_created.is_pro===true); if(!_created.username){ setShowUsernamePrompt(true); } }
 } catch(e) {}
 }
 };

