 const [buildingSlip, setBuildingSlip] = useState(false); // user is actively editing/adding to their slip
 // Entering the builder ALWAYS hydrates it from the locked snapshot and drops the
 // read-only view. That used to live only on the "Add picks"/"Edit" buttons — which are
 // hidden while buildingSlip is true — so arriving from the Bet Browser with a partly
 // submitted slip showed the locked list: no multiplier picker, no lock button, and the
 // new pick had nowhere to go.
 useEffect(()=>{
  if(!buildingSlip) return;
  if(isSoloMode){
   if(soloSavedPicks && soloSavedPicks.flexPicks){ setSoloFlexPicks(soloSavedPicks.flexPicks); setSoloSavedPicks(null); setSoloSubmitted(false); }
  } else {
   if(savedPicks && savedPicks.flexPicks){ setFlexPicks(savedPicks.flexPicks); setSavedPicks(null); setSubmitted(false); }
  }
 }, [buildingSlip, savedPicks, soloSavedPicks, isSoloMode]);
 useEffect(()=>{ if(buildingSlip){ try{ posthog.capture('builder_opened', { league_id: activeLeagueId }); }catch(e){} } }, [buildingSlip]);
 const [selectedMatchup, setSelectedMatchup] = useState(null);
 const [pastMatchupPicks, setPastMatchupPicks] = useState({my:[], opp:[]});
 const [pastMatchupLoading, setPastMatchupLoading] = useState(false);
 useEffect(()=>{
 const phone = document.querySelector('.phone');
 if(phone) phone.style.overflow = selectedMatchup ? 'visible' : 'hidden';
 }, [selectedMatchup]); // week number of selected past matchup // locked picks for the week
 const chatRef=useRef(null);
 // ── Chat reactions + GIFs (approved mockup 19 Jul 2026) ──
 const REACTION_SET=["\uD83D\uDC4D","\uD83D\uDE02","\uD83D\uDD25","\uD83D\uDC80","\uD83C\uDFAF","\uD83E\uDD21"];
 const [chatReactions,setChatReactions]=useState({});   // message_id -> [{user_id,emoji}]
 const [reactFor,setReactFor]=useState(null);           // message id with picker open
 const [gifOpen,setGifOpen]=useState(false);
 const [gifQ,setGifQ]=useState("");
 const [gifResults,setGifResults]=useState([]);
 const [gifLoading,setGifLoading]=useState(false);
 const gifDebounce=useRef(null);
 const longPressT=useRef(null);
 // Close the reaction picker on any tap outside it. A document listener instead of a
 // z-indexed overlay: the chat sits inside several CSS stacking contexts (.body etc.),
 // where overlay-vs-picker z-order is fragile. Deferred a tick so the opening long-press
 // doesn't immediately close it.
 useEffect(()=>{
   if(reactFor==null) return;
   const close=(e)=>{ try{ if(e.target && e.target.closest && e.target.closest(".pk-react-picker")) return; }catch(err){} setReactFor(null); };
   const t=setTimeout(()=>document.addEventListener("pointerdown",close,true),50);
   return ()=>{ clearTimeout(t); document.removeEventListener("pointerdown",close,true); };
 }, [reactFor]);
