 const subscribeToMessages = (leagueId) => {
 return supabase
 .channel(`chat:${leagueId}`)
 .on("postgres_changes", {
 event: "INSERT",
 schema: "public",
 table: "league_messages",
 filter: `league_id=eq.${leagueId}`,
 }, payload => {
 setMessages(prev => {
 // Avoid duplicates — remove any temp optimistic message with same content/user
 const filtered = prev.filter(m => 
 !(m.id?.toString().startsWith("temp_") && 
 m.user_id===payload.new.user_id && 
 m.message===payload.new.message)
 );
 return [...filtered, payload.new];
 });
 setTimeout(()=>{if(chatRef.current)chatRef.current.scrollTop=chatRef.current.scrollHeight;},50);
 })
 .on("postgres_changes", {
 event: "*",
 schema: "public",
 table: "chat_reactions",
 filter: `league_id=eq.${leagueId}`,
 }, payload => {
 setChatReactions(prev=>{
   const next={...prev};
   if(payload.eventType==="INSERT"){ const r=payload.new; const arr=(next[r.message_id]||[]); if(!arr.some(x=>x.user_id===r.user_id&&x.emoji===r.emoji)) next[r.message_id]=[...arr,{user_id:r.user_id,emoji:r.emoji}]; }
   else if(payload.eventType==="DELETE"){ const r=payload.old; if(r&&r.message_id) next[r.message_id]=(next[r.message_id]||[]).filter(x=>!(x.user_id===r.user_id&&x.emoji===r.emoji)); }
   return next;
 });
 })
 .subscribe();
 };

 useEffect(()=>{
 supabase.auth.getSession().then(({data:{session}})=>{
 const u = session?.user??null;
 setUser(u);
 if(u) { fetchLeagues(u.id); fetchAllMyStats(u.id); fetchUserProfile(u.id); }
 });
 supabase.auth.onAuthStateChange((_e,session)=>{
 if(_e==="PASSWORD_RECOVERY"){ setRecoveryMode(true); }
 const u = session?.user??null;
 if((u?.id ?? null) !== lastAuthUidRef.current){
   // account actually changed (switch or sign-out) — wipe the previous account's
   // in-memory data so it can't flash on the next account.
   setSoloWeeks([]); setSavedPicks(null); setSoloSavedPicks(null); setSoloFreePicks([]);
   setRealLeagues([]); setWeekPicks([]); setLeagueMembers([]); setAllMyStats(null); setUserProfile(null);
   lastAuthUidRef.current = u?.id ?? null;
 }
 setUser(u);
 if(u) { fetchLeagues(u.id); fetchAllMyStats(u.id); fetchUserProfile(u.id); } else { try{ posthog.reset(); }catch(e){} }
 });
 setTimeout(()=>setAnim(true),80);
 // (a 1s interval used to tick a countdown state here that nothing rendered —
 //  it re-reconciled the entire App tree every second for no output)
 },[]);

 // Solo home: fetch the live solo sport so the ticker + Plok's Play of the Day reflect the real live sport, not stale league data.
 useEffect(()=>{
 if(!isSoloMode || !user) return;
 fetchLiveOdds(soloSport||"mlb");
 }, [isSoloMode, soloSport, user]);

 useEffect(()=>{
 if(!activeLeagueId||!user) return;
 if(isSoloMode) return; // solo mode - no league data to fetch
 // Clear stale data immediately when league switches
 setWeekPicks([]);
 setLeagueMembers([]);
 setRealStandings([]);
 setLeagueTrophies([]);
 setSavedPicks(null);
 fetchLeagueMembers(activeLeagueId, user.id);
 fetchStandings(activeLeagueId);
 fetchLeagueTrophies(activeLeagueId);
 const lg2 = realLeagues.find(l=>l.id===activeLeagueId);
 // Always fetch odds even if lg2 not loaded yet — fetch all sports
 // Never guess the sport. Until the league row has loaded there is nothing safe to
 // fetch, and guessing bills the Odds API for a sport nobody is playing.
 const leagueSportsToFetch = lg2?.sports || (lg2?.sport ? [lg2.sport] : (activeLeague?.sport ? [activeLeague.sport] : null));
 if(leagueSportsToFetch) leagueSportsToFetch.forEach(sp => fetchLiveOdds(sp));
 if(lg2) {
 const week = lg2.current_week||lg2.week||1;
 fetchMyPicks(activeLeagueId, week, user.id, lg2); // load locked picks on entry; slip view prefers an active draft so this never clobbers one
 fetchSchedule(activeLeagueId, user.id);
 fetchLeaguePowerUps(activeLeagueId, user.id);
 // Restore saved picks from localStorage for this specific league+week
 try {
 const stored = localStorage.getItem(`linedup_picks_${activeLeagueId}_wk${week}`);
 if(stored) setSavedPicks(JSON.parse(stored));
 } catch(e) {}
 }
  // NOTE: deliberately NOT keyed on `screen`. This is league-ENTRY work (members,
  // standings, odds, locked picks). Keying on screen re-ran the whole block every time you
  // navigated Bet Browser -> Picks, which re-fetched odds and rehydrated picks from the DB,
  // clobbering the in-progress draft. That was the "add a pick, it vanishes" bug.
  },[activeLeagueId, user]);

  // Odds fetch is SEPARATE from league-entry so it can retry when realLeagues finally
  // loads (first entry often runs before the league object exists -> odds fetched for the
  // wrong/fallback sport, or not at all -> empty Bet Browser until a manual refresh). This
  // effect carries NO pick/draft logic, so re-running it can never wipe a build.
  useEffect(()=>{
    if(isSoloMode || !activeLeagueId || !user) return;
    const lg2 = realLeagues.find(l=>l.id===activeLeagueId);
    const sports = lg2?.sports || (lg2?.sport ? [lg2.sport] : (activeLeague?.sport ? [activeLeague.sport] : null));
    if(sports) sports.forEach(sp => fetchLiveOdds(sp));
  }, [activeLeagueId, user, isSoloMode, realLeagues.length, screen==="browser"]);

  // Odds are safe to (re)fetch whenever you enter a league OR open the bet browser — they
  // only populate liveOdds, never touch flexPicks/savedPicks. This is separate from the
  // league-entry effect above precisely so navigating to the browser refreshes the board
  // WITHOUT re-running the pick rehydrate that was wiping the draft.
  useEffect(()=>{
    if(isSoloMode || !activeLeagueId || !user) return;
    if(screen!=="browser" && screen!=="picks") return;
    const lg2 = realLeagues.find(l=>l.id===activeLeagueId);
    const sports = lg2?.sports || (lg2?.sport ? [lg2.sport] : (activeLeague?.sport ? [activeLeague.sport] : null));
    if(sports) sports.forEach(sp => { const have = liveOdds[sp]; if(!have || !have.ml || !have.ml.length) fetchLiveOdds(sp); });
  }, [activeLeagueId, isSoloMode, user, screen]);

 // Pull-to-refresh target. The driver fires pk:refresh; whatever the current screen is
 // about gets re-pulled, and pk:refresh-done stops the spinner. No dep array on purpose:
 // a stale closure here would refresh the league you were looking at five minutes ago.
 useEffect(()=>{
   const onRefresh = ()=>{
     const done = ()=>{ try{ window.dispatchEvent(new CustomEvent("pk:refresh-done")); }catch(e){} };
     try{
       const jobs = [];
       if(isSoloMode){
         jobs.push(fetchLiveOdds(soloSport||"mlb"));
       } else if(activeLeagueId && user){
         const lg2 = realLeagues.find(l=>l.id===activeLeagueId);
         const sports = lg2?.sports || (lg2?.sport ? [lg2.sport] : (activeLeague?.sport ? [activeLeague.sport] : null));
         if(sports) sports.forEach(sp => jobs.push(fetchLiveOdds(sp)));
         jobs.push(fetchStandings(activeLeagueId));
       }
       if(!jobs.length){ done(); return; }
       Promise.allSettled(jobs).then(done, done);
     }catch(e){ done(); }
   };
   try{ window.addEventListener("pk:refresh", onRefresh); }catch(e){}
   return ()=>{ try{ window.removeEventListener("pk:refresh", onRefresh); }catch(e){} };
 });

 useEffect(()=>{ setBuildingSlip(false); }, [activeLeagueId, isSoloMode]);

 // Rehydrate the solo home's locked-slip card after a reload (in-memory state is lost otherwise).
 // Guarded by week so a slip from a prior, already-graded week never shows as current.
 useEffect(()=>{
 if(isSoloMode && !soloSavedPicks){
 try{
 const _s = localStorage.getItem("picklock_solo_locked");
 if(_s){ const _p = JSON.parse(_s); if(_p && _p.week===soloWeekNum()){ if(_p.freePicks){ setSoloSavedPicks({freePicks:_p.freePicks, lockedAt:_p.lockedAt, week:_p.week}); } else if(_p.flexPicks){ setSoloSavedPicks({flexPicks:_p.flexPicks, lockedAt:_p.lockedAt, week:_p.week}); } } }
 }catch(e){}
 }
 },[isSoloMode, soloWeeks, soloSavedPicks]);

 // Persist + restore the UNLOCKED solo draft so in-progress picks survive leaving/reopening the app.
 useEffect(()=>{
   if(!isSoloMode){ return; }
   try{
     const _d = localStorage.getItem("picklock_solo_draft");
     if(_d){ const arr = JSON.parse(_d); if(Array.isArray(arr) && arr.length){ const _live = arr.filter(b=> !b || !b.gameTime || Date.parse(b.gameTime) > Date.now()); if(_live.length) setSoloFreePicks(prev=> (prev && prev.length) ? prev : _live); } }
   }catch(e){}
   soloDraftReady.current = true;
 },[isSoloMode]);
 useEffect(()=>{
   if(!soloDraftReady.current) return;
   try{ if(soloFreePicks && soloFreePicks.length) localStorage.setItem("picklock_solo_draft", JSON.stringify(soloFreePicks)); else localStorage.removeItem("picklock_solo_draft"); }catch(e){}
 },[soloFreePicks]);

 useEffect(()=>{
 if(!activeLeagueId||!user) return;
 if(isSoloMode) return;
 const lg = realLeagues.find(l=>l.id===activeLeagueId);
 if(lg) fetchWeekPicks(activeLeagueId, lg.current_week||lg.week||1);
 },[activeLeagueId, user, screen]);

 useEffect(()=>{if(chatRef.current)chatRef.current.scrollTop=chatRef.current.scrollHeight;},[messages]);

 useEffect(()=>{
 if(screen==="chat"&&activeLeague?.id) {
 fetchMessages(activeLeague.id);
 const sub = subscribeToMessages(activeLeague.id);
 return ()=>{ supabase.removeChannel(sub); };
 }
 },[screen, activeLeague?.id]);

 const spinWheel=()=>{
 if(spinning||!puEnabled)return;
 setSpinning(true);setWonPU(null);
 const segA=360/WHEEL_ITEMS.length;
 const winIdx=Math.floor(Math.random()*WHEEL_ITEMS.length);
 const final=wheelAngle+(5+Math.random()*3)*360+(360-winIdx*segA-segA/2);
 setWheelAngle(final);
 setTimeout(()=>{setWonPU(WHEEL_ITEMS[winIdx]);setSpinning(false);setTimeout(()=>setShowWin(true),400);},4000);
 };

 const claimPU=async()=>{
 if(wonPU && user && activeLeague?.id) {
 const week = activeLeague.current_week||activeLeague.week||1;
 // Save power-up to DB
 const {data:newPU} = await supabase.from("league_power_ups").insert({
 league_id: activeLeague.id,
 user_id: user.id,
 power_up_id: wonPU.id,
 week_earned: week,
 used: false,
 }).select().single();
 setMyPUs(p=>[...p, {...wonPU, dbId: newPU?.id}]);
 // Decrement wheel_spins in DB
 const newSpins = Math.max(0, wheelSpins-1);
 await supabase.from("league_members")
 .update({wheel_spins: newSpins})
 .eq("league_id", activeLeague.id)
 .eq("user_id", user.id);
 setWheelSpins(newSpins);
 }
 setShowWin(false);setShowWheel(false);setWonPU(null);
 };

 const usePU=async(pu, context, key)=>{
 // Mark as used in DB
 if(pu.dbId) {
 await supabase.from("league_power_ups").update({used:true}).eq("id",pu.dbId);
 }
 // Remove from local inventory
 setMyPUs(p=>p.filter(x=>x.dbId!==pu.dbId));
 // Apply to the right context
 if(context==="picks") setActivatedPUs(p=>({...p,[key]:pu}));
 if(context==="matchup") setMatchupPUs(p=>({...p,[key]:pu}));
 setShowPUModal(null);
 };
 const selectBet=(slotId,bet)=>{
 if(slotId==="longshot"){setLsBets(p=>p.find(b=>b.id===bet.id)?p.filter(b=>b.id!==bet.id):[...p,bet]);}
 else{setPicks(p=>({...p,[slotId]:bet}));setActiveSlot(null);}
 };
 const clearPick=slotId=>{if(slotId==="longshot")setLsBets([]);else setPicks(p=>({...p,[slotId]:null}));};
 const sendMsg=async()=>{
 if(!chatMsg.trim()||!user||!activeLeague?.id) return;
 const msg = chatMsg.trim();
 const username = userProfile?.username || user.email?.split("@")[0] || "Unknown";
 setChatMsg("");
 // Optimistically add message to local state immediately
 const optimistic = {
 id: `temp_${Date.now()}`,
 league_id: activeLeague.id,
 user_id: user.id,
 username,
 message: msg,
 created_at: new Date().toISOString(),
 };
 setMessages(prev=>[...prev, optimistic]);
 setTimeout(()=>{if(chatRef.current)chatRef.current.scrollTop=chatRef.current.scrollHeight;},50);
 // Then save to Supabase
 await supabase.from("league_messages").insert({
 league_id: activeLeague.id,
 user_id: user.id,
 username,
 message: msg,
 });
 };

 const parlay=calcParlay(picks,lsBets,SLOTS);
 const lsO=calcLS(lsBets);
 const allFilled=Object.values(picks).every(v=>v)&&lsBets.length>=2;

 const baseStandings = realStandings.length > 0 ? realStandings.map(s=>({
 rank: s.rank,
 userId: s.userId,
 name: s.isYou ? "You" : s.name,
 record: s.record,
 streak: s.streak,
 units: `+${s.points}`,
 roi: s.wpct,
 streak: "—",
 wpct: s.wpct,
 wr: [],
 points: s.points,
 isYou: s.isYou,
 })) : leagueMembers.length > 0 ? leagueMembers.map((m,i)=>({
 rank: i+1,
 userId: m.userId,
 name: m.isYou ? "You" : m.name,
 record: "0-0",
 units: "0",
 roi: "0%",
 streak: "—",
 wpct: "0%",
 wr: [],
 points: 0,
 isYou: m.isYou,
 })) : [];

 const sorted=[...baseStandings].sort((a,b)=>{
 if(sortBy==="roi") return parseFloat(b.roi)-parseFloat(a.roi);
 if(sortBy==="units") return parseFloat(b.units)-parseFloat(a.units);
 if(sortBy==="wpct") return parseFloat(b.wpct)-parseFloat(a.wpct);
 // Default: wins first, then points as tiebreaker
 const aWins = parseInt((a.record||"0-0").split("-")[0])||0;
 const bWins = parseInt((b.record||"0-0").split("-")[0])||0;
 if(bWins !== aWins) return bWins - aWins;
 return (b.points||0) - (a.points||0);
 });

