 {(()=>{ const seen={},d=[]; newLeaguePool.forEach(v=>{seen[v]=(seen[v]||0)+1;}); Object.keys(seen).forEach(k=>{if(seen[k]>1)d.push(k+"×");}); return d.length?<div style={{fontSize:11,fontWeight:700,color:IOS.orange}}>Repeats: {d.join(", ")}</div>:null; })()}
